const express = require('express');
const axios = require('axios');
const crypto = require('crypto');

const app = express();

// Internal metadata service credentials
let INTERNAL_API_KEY = crypto.randomBytes(32).toString('hex');
let PREVIOUS_KEY = null;

// Credential rotation mechanism
function rotateCredentials() {
  PREVIOUS_KEY = INTERNAL_API_KEY;
  INTERNAL_API_KEY = crypto.randomBytes(32).toString('hex');
  // Grace period: previous key valid for 2s after rotation
  setTimeout(() => { PREVIOUS_KEY = null; }, 2000);
}

// Rotate every 60 seconds
setInterval(rotateCredentials, 60000);

// Middleware to validate internal API requests
function validateInternalRequest(req, res, next) {
  const providedKey = req.headers['x-internal-key'];
  if (providedKey === INTERNAL_API_KEY || (PREVIOUS_KEY && providedKey === PREVIOUS_KEY)) {
    return next();
  }
  return res.status(403).json({ error: 'Invalid credentials' });
}

// Public redirect endpoint - used for OAuth/SSO callbacks
app.get('/auth/callback', (req, res) => {
  const { redirect_uri, state } = req.query;

  // Basic validation - must start with http
  if (!redirect_uri || !redirect_uri.startsWith('http')) {
    return res.status(400).json({ error: 'Invalid redirect_uri' });
  }

  // Log the redirect for audit
  console.log(`[AUTH] Redirecting to: ${redirect_uri} with state: ${state}`);

  return res.redirect(302, redirect_uri);
});

// Server-side fetch endpoint - used by frontend to proxy API calls
app.get('/api/fetch', async (req, res) => {
  const { url } = req.query;

  if (!url) {
    return res.status(400).json({ error: 'URL parameter required' });
  }

  try {
    // Follow redirects (default axios behavior)
    const response = await axios.get(url, {
      timeout: 5000,
      maxRedirects: 5,
      headers: {
        'X-Internal-Key': INTERNAL_API_KEY,
        'X-Request-Source': 'api-proxy'
      }
    });

    return res.json({
      status: response.status,
      data: response.data
    });
  } catch (error) {
    return res.status(502).json({ 
      error: 'Fetch failed', 
      message: error.message 
    });
  }
});

